#include <stdio.h>

int main() {
    int numbers[] = {4, 8, 15, 16, 23, 42};
    int n = sizeof(numbers) / sizeof(numbers[0]);
    int target = 23, index = -1;

    for (int i = 0; i < n; i++) {
        if (numbers[i] == target) {
            index = i;
            break;
        }
    }

    if (index != -1)
        printf("Found %d at index %d\n", target, index);
    else
        printf("%d not found\n", target);

    return 0;
}
